      "code": "import impl


def test_non_ascii_digits_rejected_as_malformed():
    # RFC 7233 / ticket: first, last, suffix must be ASCII digits only.
    # Arabic-Indic digits (U+0660 '0'..U+0669 '9') are Unicode decimal digits
    # that Python's re \d and int() would happily accept, but they are not
    # ASCII digits, so the header must be treated as malformed and ignored,
    # meaning the whole representation is returned.
    header = "bytes=\u0660-\u0665"  # looks like "0-5" but uses non-ASCII digits
    length = 1000
    assert impl.resolve_range(header, length) == [(0, length - 1)]
